BEGIN;
CREATE TABLE schema_migrations(version text PRIMARY KEY);
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL,password_hash text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE user_roles(user_id uuid REFERENCES users,role text CHECK(role IN('ADMIN','STUDENT','TEACHER','CANTEEN','PARKING')),PRIMARY KEY(user_id,role));
CREATE TABLE students(id uuid PRIMARY KEY,user_id uuid UNIQUE REFERENCES users,student_code text UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE devices(id uuid PRIMARY KEY,name text NOT NULL,token_hash text UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE student_cards(id uuid PRIMARY KEY,student_id uuid NOT NULL REFERENCES students,uid_hmac text NOT NULL,status text NOT NULL CHECK(status IN('ACTIVE','REVOKED')),expires_at timestamptz);
CREATE UNIQUE INDEX one_active_uid ON student_cards(uid_hmac) WHERE status='ACTIVE';
CREATE TABLE classes(id uuid PRIMARY KEY,code text UNIQUE NOT NULL);
CREATE TABLE teaching_assignments(class_id uuid REFERENCES classes,teacher_id uuid REFERENCES users,PRIMARY KEY(class_id,teacher_id));
CREATE TABLE enrollments(class_id uuid REFERENCES classes,student_id uuid REFERENCES students,PRIMARY KEY(class_id,student_id));
CREATE TABLE class_sessions(id uuid PRIMARY KEY,class_id uuid NOT NULL REFERENCES classes,status text NOT NULL CHECK(status IN('OPEN','CLOSED')),late_after timestamptz NOT NULL);
CREATE TABLE session_roster(session_id uuid REFERENCES class_sessions,student_id uuid REFERENCES students,PRIMARY KEY(session_id,student_id));
CREATE TABLE session_devices(session_id uuid REFERENCES class_sessions,device_id uuid REFERENCES devices,released_at timestamptz,PRIMARY KEY(session_id,device_id));
CREATE UNIQUE INDEX device_one_session ON session_devices(device_id) WHERE released_at IS NULL;
CREATE TABLE face_profiles(id uuid PRIMARY KEY,student_id uuid NOT NULL REFERENCES students,model_version text NOT NULL,encrypted_template bytea NOT NULL,key_id text NOT NULL,consent_reference text NOT NULL,status text NOT NULL CHECK(status IN('ACTIVE','REVOKED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_face ON face_profiles(student_id,model_version) WHERE status='ACTIVE';
CREATE TABLE ledger_accounts(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN('STUDENT','CANTEEN','PARKING','SIM_SOURCE')),balance bigint NOT NULL DEFAULT 0,CHECK(kind='SIM_SOURCE' OR balance>=0));
CREATE TABLE wallets(id uuid PRIMARY KEY,student_id uuid UNIQUE NOT NULL REFERENCES students,account_id uuid UNIQUE NOT NULL REFERENCES ledger_accounts,UNIQUE(id,student_id));
CREATE TABLE menu_items(id uuid PRIMARY KEY,name text NOT NULL,price bigint NOT NULL CHECK(price>0),price_version integer NOT NULL);
CREATE TABLE canteen_orders(id uuid PRIMARY KEY,student_id uuid NOT NULL REFERENCES students,total bigint NOT NULL CHECK(total>0),status text NOT NULL CHECK(status IN('PENDING','PAID','CANCELLED','REFUNDED')),UNIQUE(id,student_id));
CREATE TABLE order_items(order_id uuid REFERENCES canteen_orders,item_id uuid REFERENCES menu_items,quantity integer NOT NULL CHECK(quantity>0),unit_price bigint NOT NULL CHECK(unit_price>0),price_version integer NOT NULL,PRIMARY KEY(order_id,item_id));
CREATE TABLE vehicles(id uuid PRIMARY KEY,student_id uuid NOT NULL REFERENCES students,vehicle_code text UNIQUE NOT NULL,UNIQUE(id,student_id));
CREATE TABLE parking_rates(id uuid PRIMARY KEY,version text UNIQUE NOT NULL,fee bigint NOT NULL CHECK(fee>=0));
CREATE TABLE parking_sessions(id uuid PRIMARY KEY,vehicle_id uuid NOT NULL,student_id uuid NOT NULL,rate_id uuid NOT NULL REFERENCES parking_rates,entered_at timestamptz NOT NULL,closed_at timestamptz,fee_amount bigint CHECK(fee_amount>=0),FOREIGN KEY(vehicle_id,student_id) REFERENCES vehicles(id,student_id),UNIQUE(id,student_id),CHECK(closed_at IS NULL OR closed_at>=entered_at));
CREATE UNIQUE INDEX vehicle_one_open_visit ON parking_sessions(vehicle_id) WHERE closed_at IS NULL;
CREATE TABLE parking_requests(id uuid PRIMARY KEY,student_id uuid NOT NULL REFERENCES students,terminal_id uuid NOT NULL REFERENCES devices,vehicle_id uuid NOT NULL REFERENCES vehicles,session_id uuid REFERENCES parking_sessions,kind text NOT NULL CHECK(kind IN('ENTRY','EXIT')),expires_at timestamptz NOT NULL);
CREATE TABLE payment_intents(id uuid PRIMARY KEY,wallet_id uuid NOT NULL,student_id uuid NOT NULL,terminal_id uuid NOT NULL REFERENCES devices,canteen_order_id uuid UNIQUE,parking_session_id uuid UNIQUE,amount bigint NOT NULL CHECK(amount>0),status text NOT NULL CHECK(status IN('PENDING','PAID','CANCELLED','EXPIRED','REFUNDED')),expires_at timestamptz NOT NULL,
 FOREIGN KEY(wallet_id,student_id) REFERENCES wallets(id,student_id),FOREIGN KEY(canteen_order_id,student_id) REFERENCES canteen_orders(id,student_id),FOREIGN KEY(parking_session_id,student_id) REFERENCES parking_sessions(id,student_id),CHECK(num_nonnulls(canteen_order_id,parking_session_id)=1));
CREATE TABLE verification_sessions(id uuid PRIMARY KEY,student_id uuid NOT NULL REFERENCES students,terminal_id uuid NOT NULL REFERENCES devices,purpose text NOT NULL CHECK(purpose IN('ATTENDANCE','PAYMENT','PARKING')),session_id uuid REFERENCES class_sessions,intent_id uuid REFERENCES payment_intents,parking_request_id uuid REFERENCES parking_requests,method text NOT NULL CHECK(method IN('RFID','FACE')),expires_at timestamptz NOT NULL,consumed_at timestamptz,CHECK((purpose='ATTENDANCE' AND session_id IS NOT NULL AND intent_id IS NULL AND parking_request_id IS NULL) OR (purpose='PAYMENT' AND intent_id IS NOT NULL AND session_id IS NULL AND parking_request_id IS NULL) OR (purpose='PARKING' AND parking_request_id IS NOT NULL AND session_id IS NULL AND intent_id IS NULL)));
CREATE TABLE attendance_records(id uuid PRIMARY KEY,session_id uuid NOT NULL,student_id uuid NOT NULL,method text NOT NULL CHECK(method IN('RFID','FACE')),status text NOT NULL CHECK(status IN('PRESENT','LATE')),received_at timestamptz NOT NULL DEFAULT clock_timestamp(),verification_id uuid REFERENCES verification_sessions,UNIQUE(session_id,student_id),FOREIGN KEY(session_id,student_id) REFERENCES session_roster);
CREATE TABLE device_events(device_id uuid REFERENCES devices,event_id uuid,payload_hash text NOT NULL,http_status integer,response jsonb,received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(device_id,event_id));
CREATE TABLE topup_requests(id uuid PRIMARY KEY,wallet_id uuid NOT NULL REFERENCES wallets,amount bigint NOT NULL CHECK(amount>0),approved_by uuid REFERENCES users);
CREATE TABLE ledger_transactions(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN('TOPUP','SALE','REVERSAL')),intent_id uuid UNIQUE REFERENCES payment_intents,topup_id uuid UNIQUE REFERENCES topup_requests,original_id uuid UNIQUE REFERENCES ledger_transactions,posted_at timestamptz NOT NULL DEFAULT now(),creation_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),CHECK((kind='SALE' AND intent_id IS NOT NULL AND topup_id IS NULL AND original_id IS NULL) OR (kind='TOPUP' AND topup_id IS NOT NULL AND intent_id IS NULL AND original_id IS NULL) OR (kind='REVERSAL' AND original_id IS NOT NULL AND intent_id IS NULL AND topup_id IS NULL)));
CREATE TABLE ledger_entries(id uuid PRIMARY KEY,transaction_id uuid NOT NULL REFERENCES ledger_transactions,account_id uuid NOT NULL REFERENCES ledger_accounts,delta bigint NOT NULL CHECK(delta<>0),UNIQUE(transaction_id,account_id));
CREATE TABLE idempotency_requests(actor_id uuid NOT NULL,key text NOT NULL,payload_hash text NOT NULL,response jsonb,PRIMARY KEY(actor_id,key));
CREATE TABLE outbox_events(id uuid PRIMARY KEY,type text NOT NULL,payload jsonb NOT NULL,published_at timestamptz);
CREATE TABLE audit_logs(id uuid PRIMARY KEY,actor_id uuid REFERENCES users,action text NOT NULL,resource_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION immutable_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Posted ledger is immutable'; END $$;
CREATE TRIGGER ledger_header_immutable BEFORE UPDATE OR DELETE ON ledger_transactions FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE TRIGGER ledger_entry_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE FUNCTION seal_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM ledger_transactions WHERE id=NEW.transaction_id AND creation_xid=pg_current_xact_id()) THEN RAISE EXCEPTION 'Entries must be created with header'; END IF;RETURN NEW; END $$;
CREATE TRIGGER entry_same_transaction BEFORE INSERT ON ledger_entries FOR EACH ROW EXECUTE FUNCTION seal_ledger();
CREATE FUNCTION check_balance() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE tx uuid; n bigint; total numeric; BEGIN
 IF TG_TABLE_NAME='ledger_transactions' THEN tx:=NEW.id; ELSE tx:=NEW.transaction_id; END IF;
 SELECT count(*),coalesce(sum(delta),0) INTO n,total FROM ledger_entries WHERE transaction_id=tx;
 IF n<2 OR total<>0 THEN RAISE EXCEPTION 'Ledger must have at least two balanced entries'; END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER header_balanced AFTER INSERT ON ledger_transactions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_balance();
CREATE CONSTRAINT TRIGGER entries_balanced AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_balance();
INSERT INTO schema_migrations VALUES('001');
COMMIT;
